int get_rfcomm_address(struct socket *sock, struct sockaddr *addr, int *len, int peer) {
    struct sockaddr_rc *saddr_rc = (struct sockaddr_rc *)addr;
    int rc;

    if (!sock || !addr || !len) {
        return -1;
    }

    if (*len < sizeof(struct sockaddr_rc)) {
        *len = 0;
        return -1;
    }

    saddr_rc->rc_family = AF_BLUETOOTH;
    saddr_rc->rc_channel = (uint8_t)1; // Default channel

    if (peer) {
        rc = sock->ops->getname(sock, (struct sockaddr *)saddr_rc, 0);
        if (rc < 0) {
            return rc;
        }
    } else {
        bacpy(&saddr_rc->rc_bdaddr, BDADDR_ANY);
    }

    *len = sizeof(struct sockaddr_rc);
    return 0;
}
